/// Streaming multinomial probabilities (river `proba.Multinomial`).
///
/// Class count is not identification `p`.
#[derive(Clone, Debug, Default)]
pub struct MultinomialProba {
    counts: HashMap<i64, f64>,
    total: f64,
    n_seen: u64,
    updates: u64,
}

impl MultinomialProba {
    /// Empty class counter.
    pub fn new() -> Self {
        Self::default()
    }

    /// Probability of the most frequent class, or NaN before the first label.
    pub fn score(&self) -> f64 {
        if self.total <= 0.0 {
            f64::NAN
        } else {
            self.counts.values().copied().fold(0.0, f64::max) / self.total
        }
    }

    /// \(\hat p(c)\) for integer class `c`.
    pub fn pmf(&self, c: i64) -> f64 {
        if self.total <= 0.0 {
            f64::NAN
        } else {
            self.counts.get(&c).copied().unwrap_or(0.0) / self.total
        }
    }
}

impl PartialFit for MultinomialProba {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let before = self.score();
        let fallback = Vector::from_iter((0..x.nrows()).map(|i| x.get(i, 0)));
        let labels = y.unwrap_or(&fallback);
        for i in 0..x.nrows().min(labels.len()) {
            let v = labels[i];
            if !v.is_finite() {
                continue;
            }
            let k = v.round() as i64;
            *self.counts.entry(k).or_insert(0.0) += 1.0;
            self.total += 1.0;
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.total;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 1;
        q.warmup = self.n_seen < 1;
        q.explanation = format!(
            "MultinomialProba n_class={} pmax={after:.6e}",
            self.counts.len()
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "multinomial class probabilities",
                "increment integer-label counts; class count is not p",
                format!("pmax={before:.6e}"),
                format!("pmax={after:.6e}"),
            ),
        )
    }
}

/// Streaming 2×2 confusion matrix (river `metrics.ConfusionMatrix`).
///
/// `x` is the prediction, `y` the label. Class count is not identification `p`.
#[derive(Clone, Debug, Default)]
pub struct OnlineConfusion {
    tp: u64,
    fp: u64,
    tn: u64,
    fn_: u64,
    n_seen: u64,
    updates: u64,
}

impl OnlineConfusion {
    /// Empty confusion matrix.
    pub fn new() -> Self {
        Self::default()
    }

    /// Accuracy, or NaN before the first labelled pair.
    pub fn score(&self) -> f64 {
        let n = self.tp + self.fp + self.tn + self.fn_;
        if n == 0 {
            f64::NAN
        } else {
            (self.tp + self.tn) as f64 / n as f64
        }
    }
}

impl PartialFit for OnlineConfusion {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let before = self.score();
        let fallback = Vector::from_iter((0..x.nrows()).map(|i| x.get(i, 0)));
        let labels = y.unwrap_or(&fallback);
        for i in 0..x.nrows().min(labels.len()) {
            let pred = x.get(i, 0);
            let truth = labels[i];
            if !pred.is_finite() || !truth.is_finite() {
                continue;
            }
            let p = pred.round() > 0.5;
            let t = truth.round() > 0.5;
            match (p, t) {
                (true, true) => self.tp += 1,
                (true, false) => self.fp += 1,
                (false, false) => self.tn += 1,
                (false, true) => self.fn_ += 1,
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 1;
        q.warmup = self.n_seen < 1;
        q.explanation = format!(
            "OnlineConfusion acc={after:.6e} tp={} fp={}",
            self.tp, self.fp
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "streaming confusion matrix",
                "increment TP/FP/TN/FN from rounded pred vs label",
                format!("acc={before:.6e}"),
                format!("acc={after:.6e}"),
            ),
        )
    }
}

