/// River `metrics.LogCosh` — online \(\log\cosh\) residual loss.
#[derive(Clone, Debug, Default)]
pub struct OnlineLogCosh {
    acc: f64,
    n: u64,
    updates: u64,
}

impl OnlineLogCosh {
    /// Empty log-cosh metric.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current mean log-cosh, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.n == 0 {
            f64::NAN
        } else {
            self.acc / self.n as f64
        }
    }
}

impl PartialFit for OnlineLogCosh {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        metric_partial(
            session,
            "log_cosh",
            x,
            y,
            self.updates,
            self.n,
            |pred, truth| {
                let e = pred - truth;
                let ae = e.abs();
                // `log(cosh(e))` = `|e| + log(1 + exp(-2|e|)) - log(2)`.
                let lch = ae + ((-2.0 * ae).exp() + 1.0).ln() - 2.0_f64.ln();
                self.acc += lch;
                self.n += 1;
                self.updates += 1;
                self.score()
            },
        )
    }
}

