/// Content-based recommender (river `reco.Content`).
///
/// `X` is `[user, item, …content]`, `y` is the rating. Item count is not
/// identification `p`.
#[derive(Clone, Debug)]
pub struct ContentReco {
    /// SGD step on content weights.
    pub learning_rate: f64,
    user_mean: HashMap<i64, (f64, u64)>,
    coef: Vector,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for ContentReco {
    fn default() -> Self {
        Self {
            learning_rate: 0.05,
            user_mean: HashMap::new(),
            coef: Vector::zeros(0),
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl ContentReco {
    /// Empty content recommender.
    pub fn new() -> Self {
        Self::default()
    }
}

impl PartialFit for ContentReco {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no ratings"),
            );
        };
        if x.ncols() < 2 {
            ctx.push(
                Issue::builder(IssueCode::DimensionMismatch)
                    .severity(Severity::Warning)
                    .message("ContentReco needs [user, item, …content]")
                    .build(),
            );
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "need two columns"),
            );
        }
        let p = x.ncols().saturating_sub(2);
        if !self.initialized {
            self.coef = Vector::zeros(p.max(1));
            self.initialized = true;
        } else if self.coef.len() != p.max(1) {
            ctx.push(
                Issue::builder(IssueCode::FeatureSpaceChangedOnline)
                    .severity(Severity::Warning)
                    .message("ContentReco content dim changed")
                    .build(),
            );
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "content dim changed"),
            );
        }
        let eta = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            0.05
        };
        let mut moved = 0.0;
        let mut sse = 0.0;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let user = x.get(i, 0).round() as i64;
            let (um, un) = self.user_mean.get(&user).copied().unwrap_or((0.0, 0));
            let mut pred = um;
            for j in 0..p.min(self.coef.len()) {
                pred += self.coef[j] * x.get(i, j + 2);
            }
            let err = pred - y[i];
            sse += err * err;
            for j in 0..p.min(self.coef.len()) {
                let step = eta * err * x.get(i, j + 2);
                self.coef[j] -= step;
                moved += step.abs();
            }
            let nxt_n = un + 1;
            let nxt_m = um + (y[i] - um) / nxt_n as f64;
            self.user_mean.insert(user, (nxt_m, nxt_n));
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(moved);
        q.information_gain = Some(moved.max(x.nrows() as f64));
        q.loss_after = Some(sse);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 2;
        q.explanation = format!(
            "ContentReco {} users, ||Δw||={moved:.6e}",
            self.user_mean.len()
        );
        if q.warmup {
            ctx.push(
                Issue::builder(IssueCode::WarmupIncomplete)
                    .incremental(q.clone())
                    .message("ContentReco has seen fewer than two ratings")
                    .build(),
            );
        }
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "user mean + content SGD",
                "residual of the user mean is fit on columns 2..; item count is not p",
                "previous user means / content weights",
                format!("{} users", self.user_mean.len()),
            ),
        )
    }
}

/// Group-wise target mean encoder (river `feature_extraction.TargetAgg`).
///
/// Group count is not identification `p`.
#[derive(Clone, Debug)]
pub struct TargetAgg {
    means: HashMap<i64, (f64, u64)>,
    n_seen: u64,
    updates: u64,
}

impl Default for TargetAgg {
    fn default() -> Self {
        Self {
            means: HashMap::new(),
            n_seen: 0,
            updates: 0,
        }
    }
}

impl TargetAgg {
    /// Empty target aggregator.
    pub fn new() -> Self {
        Self::default()
    }
}

impl PartialFit for TargetAgg {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no target"),
            );
        };
        if x.ncols() < 1 {
            ctx.push(
                Issue::builder(IssueCode::EmptyMatrix)
                    .severity(Severity::Warning)
                    .message("TargetAgg needs a group column")
                    .build(),
            );
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no group column"),
            );
        }
        let mut moved = 0.0;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let g = x.get(i, 0).round() as i64;
            let (m, n) = self.means.get(&g).copied().unwrap_or((0.0, 0));
            let nxt_n = n + 1;
            let nxt = m + (y[i] - m) / nxt_n as f64;
            moved += (nxt - m).abs();
            self.means.insert(g, (nxt, nxt_n));
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(moved);
        q.information_gain = Some(moved);
        q.still_identified = !self.means.is_empty();
        q.warmup = self.means.is_empty();
        q.explanation = format!("TargetAgg {} groups, ||Δμ||={moved:.6e}", self.means.len());
        if q.warmup {
            ctx.push(
                Issue::builder(IssueCode::WarmupIncomplete)
                    .incremental(q.clone())
                    .message("TargetAgg has no groups yet")
                    .build(),
            );
        }
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "group target means",
                "Welford mean of y keyed by X[:,0]; group count is not p",
                "previous group means",
                format!("{} groups", self.means.len()),
            ),
        )
    }
}

/// Higher-order factorization machine (river `reco.HoFM`).
///
/// Factor count is not identification `p`. A design with fewer than three
/// columns has no 3-way term.
#[derive(Clone, Debug)]
pub struct HoFm {
    /// Pairwise factor width.
    pub n_factors: usize,
    /// SGD step.
    pub learning_rate: f64,
    w0: f64,
    w: Vector,
    v: Matrix,
    t3: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for HoFm {
    fn default() -> Self {
        Self {
            n_factors: 2,
            learning_rate: 0.05,
            w0: 0.0,
            w: Vector::zeros(0),
            v: Matrix::zeros(0, 0),
            t3: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl HoFm {
    /// HoFM with `k` pairwise factors.
    pub fn new(n_factors: usize) -> Self {
        Self {
            n_factors: n_factors.max(1),
            ..Self::default()
        }
    }

    fn predict_row(&self, x: &Matrix, i: usize) -> f64 {
        let p = x.ncols().min(self.w.len());
        let mut s = self.w0;
        for j in 0..p {
            s += self.w[j] * x.get(i, j);
        }
        let k = self.v.ncols();
        if k > 0 && self.v.nrows() > 0 {
            for f in 0..k {
                let mut sum_vx = 0.0;
                let mut sum_v2x2 = 0.0;
                for j in 0..p.min(self.v.nrows()) {
                    let vjf = self.v.get(j, f);
                    let xj = x.get(i, j);
                    sum_vx += vjf * xj;
                    sum_v2x2 += vjf * vjf * xj * xj;
                }
                s += 0.5 * (sum_vx * sum_vx - sum_v2x2);
            }
        }
        if p >= 3 {
            s += self.t3 * x.get(i, 0) * x.get(i, 1) * x.get(i, 2);
        }
        s
    }
}

impl PartialFit for HoFm {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no ratings"),
            );
        };
        let p = x.ncols();
        let k = self.n_factors.max(1);
        if !self.initialized {
            self.w = Vector::zeros(p.max(1));
            self.v = Matrix::from_fn(p.max(1), k, |_, _| 0.01);
            self.initialized = true;
        } else if self.w.len() != p.max(1) {
            ctx.push(
                Issue::builder(IssueCode::FeatureSpaceChangedOnline)
                    .severity(Severity::Warning)
                    .message("HoFm feature dim changed")
                    .build(),
            );
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let eta = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            0.05
        };
        let mut sse = 0.0;
        let mut moved = 0.0;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let pred = self.predict_row(x, i);
            let err = pred - y[i];
            sse += err * err;
            self.w0 -= eta * err;
            moved += (eta * err).abs();
            let kf = k.min(self.v.ncols());
            let mut sum_f = vec![0.0; kf];
            for f in 0..kf {
                for j in 0..p.min(self.v.nrows()) {
                    sum_f[f] += self.v.get(j, f) * x.get(i, j);
                }
            }
            for j in 0..p.min(self.w.len()) {
                let xj = x.get(i, j);
                let step = eta * err * xj;
                self.w[j] -= step;
                moved += step.abs();
                if j >= self.v.nrows() {
                    continue;
                }
                for f in 0..kf {
                    let vjf = self.v.get(j, f);
                    let grad = err * xj * (sum_f[f] - vjf * xj);
                    let nxt = vjf - eta * grad;
                    self.v.set(j, f, nxt);
                    moved += (eta * grad).abs();
                }
            }
            if p >= 3 {
                let trip = x.get(i, 0) * x.get(i, 1) * x.get(i, 2);
                let step = eta * err * trip;
                self.t3 -= step;
                moved += step.abs();
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(moved);
        q.information_gain = Some(moved.max(x.nrows() as f64));
        q.loss_after = Some(sse);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 2;
        q.explanation = format!("HoFM ||Δ||={moved:.6e} sse={sse:.6e}");
        if q.warmup {
            ctx.push(
                Issue::builder(IssueCode::WarmupIncomplete)
                    .incremental(q.clone())
                    .message("HoFm has seen fewer than two rows")
                    .build(),
            );
        }
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "linear + pairwise FM + optional 3-way term",
                "SGD on w, V and the first-three-column product; factor count is not p",
                "previous HoFM weights",
                format!("n_seen={}", self.n_seen),
            ),
        )
    }
}

impl Predict for AdaBoundRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter(
            (0..x.nrows()).map(|i| self.predict_row(x, i)),
        ))
    }
}

/// Yogi linear regressor (river `optim.Yogi`).
///
/// Second-moment updates subtract a signed increment so \(v\) can decrease.
#[derive(Clone, Debug)]
pub struct YogiRegressor {
    /// Step \(\eta\).
    pub learning_rate: f64,
    /// First-moment decay.
    pub beta1: f64,
    /// Second-moment decay.
    pub beta2: f64,
    /// Diagonal floor.
    pub eps: f64,
    /// Prepend an intercept column.
    pub fit_intercept: bool,
    coef: Vector,
    m: Vector,
    v: Vector,
    t: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for YogiRegressor {
    fn default() -> Self {
        Self {
            learning_rate: 0.05,
            beta1: 0.9,
            beta2: 0.999,
            eps: 1e-8,
            fit_intercept: true,
            coef: Vector::zeros(0),
            m: Vector::zeros(0),
            v: Vector::zeros(0),
            t: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl YogiRegressor {
    /// Default Yogi regressor.
    pub fn new() -> Self {
        Self::default()
    }

    fn predict_row(&self, x: &Matrix, i: usize) -> f64 {
        let z = row_aug(x, i, self.fit_intercept);
        let n = z.len().min(self.coef.len());
        let mut s = 0.0;
        for j in 0..n {
            s += self.coef[j] * z[j];
        }
        s
    }
}

impl PartialFit for YogiRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no target"),
            );
        };
        let dim = online_linear_dim(self.fit_intercept, x.ncols());
        if !self.initialized {
            self.coef = Vector::zeros(dim);
            self.m = Vector::zeros(dim);
            self.v = Vector::zeros(dim);
            self.initialized = true;
        } else if self.coef.len() != dim {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "feature space changed"),
            );
        }
        let before = self.coef.clone();
        let eta = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            0.05
        };
        let b1 = self.beta1.clamp(0.0, 0.999);
        let b2 = self.beta2.clamp(0.0, 0.999);
        let eps = if self.eps.is_finite() && self.eps > 0.0 {
            self.eps
        } else {
            1e-8
        };
        let mut loss_before = 0.0;
        let mut loss_after = 0.0;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let z = row_aug(x, i, self.fit_intercept);
            let pred = self.predict_row(x, i);
            let err = pred - y[i];
            loss_before += err * err;
            self.t += 1.0;
            let corr1 = 1.0 - b1.powf(self.t);
            let corr2 = 1.0 - b2.powf(self.t);
            for j in 0..dim {
                let g = err * z[j];
                self.m[j] = b1 * self.m[j] + (1.0 - b1) * g;
                let g2 = g * g;
                self.v[j] -= (1.0 - b2) * (self.v[j] - g2).signum() * g2;
                let mhat = self.m[j] / corr1.max(1e-18);
                let vhat = self.v[j].abs() / corr2.max(1e-18);
                self.coef[j] -= eta * mhat / (vhat.sqrt() + eps);
            }
            let after = self.predict_row(x, i);
            let ea = after - y[i];
            loss_after += ea * ea;
            self.n_seen += 1;
        }
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            x.nrows(),
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen >= dim as u64,
            self.n_seen < 4,
            "Yogi linear weights",
            "Adam first moment with a signed second-moment correction",
        );
        finish_explain(ctx, expl)
    }
}

