#[derive(Clone, Debug)]
struct LogitLeaf {
    theta: Vector,
    n: u64,
}

impl LogitLeaf {
    fn new(p: usize) -> Self {
        Self {
            theta: Vector::zeros(p),
            n: 0,
        }
    }

    fn predict(&self, z: &Vector) -> f64 {
        let mut s = 0.0;
        for j in 0..self.theta.len().min(z.len()) {
            s += self.theta[j] * z[j];
        }
        sigmoid(s.clamp(-20.0, 20.0))
    }

    fn update(&mut self, z: &Vector, y: f64, lr: f64) -> f64 {
        if self.theta.len() != z.len() {
            *self = Self::new(z.len());
        }
        let p_hat = self.predict(z);
        let t = as01(y);
        let err = p_hat - t;
        let mut dn = 0.0;
        for j in 0..self.theta.len().min(z.len()) {
            let d = lr * err * z[j];
            self.theta[j] -= d;
            dn += d * d;
        }
        self.n += 1;
        dn.sqrt()
    }
}

fn binary_gini(n: f64, pos: f64) -> f64 {
    if n <= 0.0 {
        return 0.0;
    }
    let p = (pos / n).clamp(0.0, 1.0);
    1.0 - p * p - (1.0 - p) * (1.0 - p)
}

/// Adaptive model rules for classification (river `rules.AMRulesClassifier`).
///
/// Hoeffding split on **Gini** of the label, logistic-SGD leaves. Distinct
/// from [`AdaptiveModelRules`] (SSE + RLS regression) and
/// [`VeryFastDecisionRules`] (named wrapper of the regressor).
#[derive(Clone, Debug)]
pub struct AMRulesClassifier {
    /// SGD step.
    pub learning_rate: f64,
    /// Hoeffding \(\delta\).
    pub delta: f64,
    p: usize,
    split: Option<(usize, f64)>,
    default: LogitLeaf,
    left: Option<LogitLeaf>,
    right: Option<LogitLeaf>,
    feat_mean: Vector,
    feat_n: u64,
    parent_n: u64,
    parent_pos: f64,
    left_n: Vector,
    left_pos: Vector,
    right_n: Vector,
    right_pos: Vector,
    updates: u64,
    n_seen: u64,
}

impl Default for AMRulesClassifier {
    fn default() -> Self {
        Self {
            learning_rate: 0.1,
            delta: 0.01,
            p: 0,
            split: None,
            default: LogitLeaf::new(0),
            left: None,
            right: None,
            feat_mean: Vector::zeros(0),
            feat_n: 0,
            parent_n: 0,
            parent_pos: 0.0,
            left_n: Vector::zeros(0),
            left_pos: Vector::zeros(0),
            right_n: Vector::zeros(0),
            right_pos: Vector::zeros(0),
            updates: 0,
            n_seen: 0,
        }
    }
}

impl AMRulesClassifier {
    /// AMRules classifier with SGD step `learning_rate`.
    pub fn new(learning_rate: f64) -> Self {
        Self {
            learning_rate,
            ..Self::default()
        }
    }

    fn ensure(&mut self, p_x: usize) {
        let p = p_x + 1;
        if self.p == p {
            return;
        }
        self.p = p;
        self.default = LogitLeaf::new(p);
        self.feat_mean = Vector::zeros(p_x);
        self.left_n = Vector::zeros(p_x);
        self.left_pos = Vector::zeros(p_x);
        self.right_n = Vector::zeros(p_x);
        self.right_pos = Vector::zeros(p_x);
    }

    fn row(x: &Matrix, i: usize) -> Vector {
        let mut z = Vector::zeros(x.ncols() + 1);
        z[0] = 1.0;
        for j in 0..x.ncols() {
            z[j + 1] = x.get(i, j);
        }
        z
    }

    fn route(&mut self, x: &Matrix, i: usize) -> &mut LogitLeaf {
        match self.split {
            Some((j, t)) if x.get(i, j) <= t => {
                if self.left.is_none() {
                    self.left = Some(LogitLeaf::new(self.p));
                }
                self.left.as_mut().unwrap()
            }
            Some((_j, _)) => {
                if self.right.is_none() {
                    self.right = Some(LogitLeaf::new(self.p));
                }
                self.right.as_mut().unwrap()
            }
            None => &mut self.default,
        }
    }

    fn maybe_split(&mut self, ctx: &mut FitCtx) -> Option<(usize, f64, f64)> {
        if self.split.is_some() || self.feat_mean.is_empty() || self.parent_n < 20 {
            return None;
        }
        let eps = ((1.0 / self.delta.max(1e-12)).ln() / (2.0 * self.parent_n as f64)).sqrt();
        let parent = binary_gini(self.parent_n as f64, self.parent_pos);
        let mut best = None;
        let mut best_gain = 0.0;
        let mut second = 0.0;
        for j in 0..self.feat_mean.len() {
            let nl = self.left_n[j];
            let nr = self.right_n[j];
            if nl < 5.0 || nr < 5.0 {
                continue;
            }
            let gl = binary_gini(nl, self.left_pos[j]);
            let gr = binary_gini(nr, self.right_pos[j]);
            let gain = parent - (nl * gl + nr * gr) / (nl + nr);
            if gain > best_gain {
                second = best_gain;
                best_gain = gain;
                best = Some((j, self.feat_mean[j], gain));
            } else if gain > second {
                second = gain;
            }
        }
        if let Some((j, t, gain)) = best {
            if gain - second > eps && gain > 0.0 {
                self.split = Some((j, t));
                self.left = Some(LogitLeaf::new(self.p));
                self.right = Some(LogitLeaf::new(self.p));
                ctx.push(
                    Issue::builder(IssueCode::ConceptDriftDetected)
                        .severity(Severity::Advisory)
                        .message(format!(
                            "AMRulesClassifier split on feature {j} at {t:.6e} (gain={gain:.6e}, ε={eps:.6e})"
                        ))
                        .build(),
                );
                return Some((j, t, gain));
            }
        }
        None
    }

    fn predict_row(&self, x: &Matrix, i: usize) -> f64 {
        let z = Self::row(x, i);
        match self.split {
            Some((j, t)) if x.get(i, j) <= t => {
                self.left.as_ref().map(|l| l.predict(&z)).unwrap_or(0.5)
            }
            Some(_) => self.right.as_ref().map(|l| l.predict(&z)).unwrap_or(0.5),
            None => self.default.predict(&z),
        }
    }
}

impl PartialFit for AMRulesClassifier {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            if self.n_seen == 0 {
                ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            }
            return finish_explain(
                ctx,
                reject_explain(self.updates, 0, self.n_seen, "AMRulesClassifier needs a target"),
            );
        };
        self.ensure(x.ncols());
        let lr = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message("AMRulesClassifier learning_rate is not a positive finite; using 0.1")
                    .build(),
            );
            0.1
        };
        let mut dsum = 0.0;
        let mut loss_before = 0.0;
        let mut loss_after = 0.0;
        let mut leaf_hits = [0u64; 3];
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            let z = Self::row(x, i);
            let pred_b = self.predict_row(x, i);
            let t = as01(y[i]);
            loss_before += -(t * (pred_b + 1e-12).ln() + (1.0 - t) * (1.0 - pred_b + 1e-12).ln());
            let which = match self.split {
                Some((j, th)) if x.get(i, j) <= th => 1,
                Some(_) => 2,
                None => 0,
            };
            leaf_hits[which] += 1;
            let dn = self.route(x, i).update(&z, y[i], lr);
            dsum += dn;
            let pred_a = self.predict_row(x, i);
            loss_after += -(t * (pred_a + 1e-12).ln() + (1.0 - t) * (1.0 - pred_a + 1e-12).ln());
            if self.split.is_none() {
                self.parent_n += 1;
                self.parent_pos += t;
                self.feat_n += 1;
                for j in 0..x.ncols() {
                    let v = x.get(i, j);
                    self.feat_mean[j] += (v - self.feat_mean[j]) / self.feat_n as f64;
                    if v <= self.feat_mean[j] {
                        self.left_n[j] += 1.0;
                        self.left_pos[j] += t;
                    } else {
                        self.right_n[j] += 1.0;
                        self.right_pos[j] += t;
                    }
                }
            }
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let split = self.maybe_split(&mut ctx);
        let identified = self.n_seen as usize > self.p.max(1);
        let warmup = self.n_seen < 10;
        let what = if let Some((j, t, g)) = split {
            format!("split on x[{j}]≤{t:.4e} gain={g:.4e}; leaf hits {leaf_hits:?}")
        } else if self.split.is_some() {
            format!("updated split logistic leaves; hits {leaf_hits:?}")
        } else {
            format!("updated default logistic leaf; hits {leaf_hits:?}")
        };
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &Vector::from_slice(&[dsum]),
            loss_before,
            loss_after,
            identified,
            warmup,
            &what,
            "logistic-SGD leaf update; a Hoeffding Gini test may grow a stump",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for AMRulesClassifier {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.p == 0 {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            if self.predict_row(x, i) >= 0.5 {
                1.0
            } else {
                0.0
            }
        })))
    }
}

/// Online pinball / quantile regressor (river `optim` + linear quantile).
///
/// SGD on \(\rho_\tau(y-x^\top\theta)\). Distinct from [`PaRegressor`]
/// (ε-insensitive) and [`OnlineQuantile`] (univariate tracker, no \(X\)).
/// \(\tau\) is not identification `p`.
#[derive(Clone, Debug)]
pub struct OnlineQuantileRegressor {
    /// Quantile level in \((0,1)\).
    pub tau: f64,
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineQuantileRegressor {
    fn default() -> Self {
        Self {
            tau: 0.5,
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineQuantileRegressor {
    /// Pinball regressor at quantile `tau`.
    pub fn new(tau: f64) -> Self {
        Self {
            tau,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineQuantileRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            if self.n_seen == 0 {
                ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            }
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "missing y"),
            );
        };
        if !self.initialized {
            if x.ncols() == 0 {
                ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
                return finish_explain(
                    ctx,
                    reject_explain(self.updates, x.nrows(), self.n_seen, "no features"),
                );
            }
            self.coef = Vector::zeros(x.ncols());
            self.initialized = true;
        } else if self.coef.len() != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "feature space changed"),
            );
        }
        let tau = if self.tau.is_finite() && self.tau > 0.0 && self.tau < 1.0 {
            self.tau
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message("OnlineQuantileRegressor tau is not in (0,1); using 0.5")
                    .build(),
            );
            0.5
        };
        let lr = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message("OnlineQuantileRegressor learning_rate is not a positive finite; using 0.05")
                    .build(),
            );
            0.05
        };
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() {
                continue;
            }
            let mut s = self.intercept;
            for j in 0..x.ncols() {
                s += self.coef[j] * x.get(i, j);
            }
            let r = y[i] - s;
            loss_before += if r >= 0.0 { tau * r } else { (tau - 1.0) * r };
            let g = if r >= 0.0 { -tau } else { 1.0 - tau };
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut sa = self.intercept;
            for j in 0..x.ncols() {
                sa += self.coef[j] * x.get(i, j);
            }
            let ra = y[i] - sa;
            loss_after += if ra >= 0.0 {
                tau * ra
            } else {
                (tau - 1.0) * ra
            };
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online pinball regressor",
            "SGD on ρ_τ(y − xθ); τ is a quantile, not identification p",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlineQuantileRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut s = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                s += self.coef[j] * x.get(i, j);
            }
            s
        })))
    }
}

fn online_glm_prepare<'a>(
    ctx: &mut FitCtx,
    x: &'a Matrix,
    y: Option<&'a Vector>,
    initialized: bool,
    n_seen: u64,
    coef: &mut Vector,
    learning_rate: f64,
    name: &str,
) -> Option<(&'a Vector, f64)> {
    inspect_online_xy(ctx, x, y);
    let Some(y) = y else {
        ctx.push(Issue::builder(IssueCode::MissingTarget).build());
        if n_seen == 0 {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
        }
        return None;
    };
    if !initialized {
        if x.ncols() == 0 {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return None;
        }
        *coef = Vector::zeros(x.ncols());
    } else if coef.len() != x.ncols() {
        ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
        return None;
    }
    let lr = if learning_rate.is_finite() && learning_rate > 0.0 {
        learning_rate
    } else {
        ctx.push(
            Issue::builder(IssueCode::InvalidWeight)
                .severity(Severity::Warning)
                .message(format!("{name} learning_rate is not a positive finite; using 0.05"))
                .build(),
        );
        0.05
    };
    Some((y, lr))
}

/// Online Poisson GLM regressor (river `linear_model` + Poisson).
///
/// Log-link SGD on \(\exp(\eta)-y\eta\). Distinct from [`OnlinePoisson`]
/// (univariate count tracker, no \(X\)).
#[derive(Clone, Debug)]
pub struct OnlinePoissonRegressor {
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlinePoissonRegressor {
    fn default() -> Self {
        Self {
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlinePoissonRegressor {
    /// Poisson GLM with step `learning_rate`.
    pub fn new(learning_rate: f64) -> Self {
        Self {
            learning_rate,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlinePoissonRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlinePoissonRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected Poisson GLM update"),
            );
        };
        self.initialized = true;
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() || y[i] < 0.0 {
                if y[i].is_finite() && y[i] < 0.0 {
                    ctx.push(
                        Issue::builder(IssueCode::NonPositiveSeries)
                            .severity(Severity::Warning)
                            .message("OnlinePoissonRegressor skipped a negative count")
                            .build(),
                    );
                }
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let eta = eta.clamp(-20.0, 20.0);
            let mu = eta.exp();
            loss_before += mu - y[i] * eta;
            let g = mu - y[i];
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ea = ea.clamp(-20.0, 20.0);
            loss_after += ea.exp() - y[i] * ea;
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online Poisson GLM",
            "SGD on exp(η) − yη; count mean, not identification p",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlinePoissonRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut eta = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                eta += self.coef[j] * x.get(i, j);
            }
            eta.clamp(-20.0, 20.0).exp()
        })))
    }
}

/// Online Gamma GLM regressor (river Gamma + log link).
///
/// SGD on \(y e^{-\eta}+\eta\). Distinct from [`OnlineGamma`] (univariate
/// tracker) and [`OnlinePoissonRegressor`] (count mean).
#[derive(Clone, Debug)]
pub struct OnlineGammaRegressor {
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineGammaRegressor {
    fn default() -> Self {
        Self {
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineGammaRegressor {
    /// Gamma GLM with step `learning_rate`.
    pub fn new(learning_rate: f64) -> Self {
        Self {
            learning_rate,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineGammaRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineGammaRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected Gamma GLM update"),
            );
        };
        self.initialized = true;
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() || y[i] <= 0.0 {
                if y[i].is_finite() && y[i] <= 0.0 {
                    ctx.push(
                        Issue::builder(IssueCode::NonPositiveSeries)
                            .severity(Severity::Warning)
                            .message("OnlineGammaRegressor skipped a non-positive response")
                            .build(),
                    );
                }
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let eta = eta.clamp(-20.0, 20.0);
            let mu = eta.exp();
            loss_before += y[i] / mu + eta;
            let g = 1.0 - y[i] / mu;
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ea = ea.clamp(-20.0, 20.0);
            loss_after += y[i] / ea.exp() + ea;
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online Gamma GLM",
            "SGD on y exp(−η) + η; mean is not identification p",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlineGammaRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut eta = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                eta += self.coef[j] * x.get(i, j);
            }
            eta.clamp(-20.0, 20.0).exp()
        })))
    }
}

/// Online Tweedie GLM regressor (compound Poisson–Gamma, log link).
///
/// Power \(p\) is not identification `p`. Distinct from
/// [`OnlineTweedieDeviance`] (metric) and [`OnlinePoissonRegressor`] (\(p=1\)).
#[derive(Clone, Debug)]
pub struct OnlineTweedieRegressor {
    /// Tweedie power in \((1,2)\). Not identification `p`.
    pub power: f64,
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineTweedieRegressor {
    fn default() -> Self {
        Self {
            power: 1.5,
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineTweedieRegressor {
    /// Tweedie GLM with variance power `power`.
    pub fn new(power: f64) -> Self {
        Self {
            power,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineTweedieRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineTweedieRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected Tweedie GLM update"),
            );
        };
        self.initialized = true;
        let pwr = if self.power.is_finite() && self.power > 1.0 && self.power < 2.0 {
            self.power
        } else {
            1.5
        };
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() || y[i] < 0.0 {
                if y[i].is_finite() && y[i] < 0.0 {
                    ctx.push(
                        Issue::builder(IssueCode::NonPositiveSeries)
                            .severity(Severity::Warning)
                            .message("OnlineTweedieRegressor skipped a negative response")
                            .build(),
                    );
                }
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let eta = eta.clamp(-20.0, 20.0);
            let mu = eta.exp();
            let inv = 1.0 - pwr;
            loss_before += mu.powf(inv) / inv - y[i] * mu.powf(-pwr) / (-pwr);
            let g = (mu - y[i]) * mu.powf(1.0 - pwr);
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ea = ea.clamp(-20.0, 20.0);
            let mua = ea.exp();
            loss_after += mua.powf(inv) / inv - y[i] * mua.powf(-pwr) / (-pwr);
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online Tweedie GLM",
            "SGD on the Tweedie unit deviance; power is not identification p",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlineTweedieRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut eta = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                eta += self.coef[j] * x.get(i, j);
            }
            eta.clamp(-20.0, 20.0).exp()
        })))
    }
}

/// Online Huber regressor (river `optim` + Huber).
///
/// SGD on the Huber piecewise loss. Distinct from [`OnlineHuber`] (rolling
/// metric) and [`PaRegressor`] (ε-insensitive).
#[derive(Clone, Debug)]
pub struct OnlineHuberRegressor {
    /// Huber threshold \(\delta>0\). Not identification `p`.
    pub delta: f64,
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineHuberRegressor {
    fn default() -> Self {
        Self {
            delta: 1.0,
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineHuberRegressor {
    /// Huber regressor with threshold `delta`.
    pub fn new(delta: f64) -> Self {
        Self {
            delta,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineHuberRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineHuberRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected Huber update"),
            );
        };
        self.initialized = true;
        let delta = if self.delta.is_finite() && self.delta > 0.0 {
            self.delta
        } else {
            1.0
        };
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() {
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let r = y[i] - eta;
            let ar = r.abs();
            loss_before += if ar <= delta {
                0.5 * r * r
            } else {
                delta * (ar - 0.5 * delta)
            };
            let g = if ar <= delta {
                -r
            } else if r >= 0.0 {
                -delta
            } else {
                delta
            };
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ra = y[i] - ea;
            let ara = ra.abs();
            loss_after += if ara <= delta {
                0.5 * ra * ra
            } else {
                delta * (ara - 0.5 * delta)
            };
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta_c = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta_c,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online Huber regressor",
            "SGD on the Huber piecewise loss; δ is not identification p",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlineHuberRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut s = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                s += self.coef[j] * x.get(i, j);
            }
            s
        })))
    }
}

/// Online negative-binomial GLM (NB2 log link).
///
/// Dispersion \(r\) is not identification `p`. Distinct from
/// [`OnlinePoissonRegressor`] (equidispersion) — this is an overdispersed
/// regression head on \(X\).
#[derive(Clone, Debug)]
pub struct OnlineNegBinRegressor {
    /// NB2 dispersion \(r>0\). Not identification `p`.
    pub r: f64,
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineNegBinRegressor {
    fn default() -> Self {
        Self {
            r: 1.0,
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineNegBinRegressor {
    /// NB2 GLM with dispersion `r`.
    pub fn new(r: f64) -> Self {
        Self {
            r,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineNegBinRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineNegBinRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected NB2 GLM update"),
            );
        };
        self.initialized = true;
        let r = if self.r.is_finite() && self.r > 0.0 {
            self.r
        } else {
            1.0
        };
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() || y[i] < 0.0 {
                if y[i].is_finite() && y[i] < 0.0 {
                    ctx.push(
                        Issue::builder(IssueCode::NonPositiveSeries)
                            .severity(Severity::Warning)
                            .message("OnlineNegBinRegressor skipped a negative count")
                            .build(),
                    );
                }
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let eta = eta.clamp(-20.0, 20.0);
            let mu = eta.exp();
            loss_before += -y[i] * eta + (y[i] + r) * (mu + r).ln();
            let g = (mu - y[i]) / (1.0 + mu / r);
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ea = ea.clamp(-20.0, 20.0);
            loss_after += -y[i] * ea + (y[i] + r) * (ea.exp() + r).ln();
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online NB2 GLM",
            "SGD on the NB2 log-link score; r is not identification p",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlineNegBinRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut eta = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                eta += self.coef[j] * x.get(i, j);
            }
            eta.clamp(-20.0, 20.0).exp()
        })))
    }
}

/// Online Beta GLM (logit quasi-likelihood on \((0,1)\)).
///
/// Rows with \(y\notin(0,1)\) are skipped with a warning and do not abort.
/// Distinct from [`OnlineBeta`] (univariate tracker) — this is a
/// fractional-response GLM.
#[derive(Clone, Debug)]
pub struct OnlineBetaRegressor {
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineBetaRegressor {
    fn default() -> Self {
        Self {
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineBetaRegressor {
    /// Beta GLM with step `learning_rate`.
    pub fn new(learning_rate: f64) -> Self {
        Self {
            learning_rate,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineBetaRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineBetaRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected Beta GLM update"),
            );
        };
        self.initialized = true;
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() || y[i] <= 0.0 || y[i] >= 1.0 {
                if y[i].is_finite() && (y[i] <= 0.0 || y[i] >= 1.0) {
                    ctx.push(
                        Issue::builder(IssueCode::NonPositiveSeries)
                            .severity(Severity::Warning)
                            .message("OnlineBetaRegressor skipped a response outside (0, 1)")
                            .build(),
                    );
                }
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let eta = eta.clamp(-20.0, 20.0);
            let mu = 1.0 / (1.0 + (-eta).exp());
            let mu = mu.clamp(1e-8, 1.0 - 1e-8);
            loss_before += -(y[i] * mu.ln() + (1.0 - y[i]) * (1.0 - mu).ln());
            let g = mu - y[i];
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ea = ea.clamp(-20.0, 20.0);
            let mua = (1.0 / (1.0 + (-ea).exp())).clamp(1e-8, 1.0 - 1e-8);
            loss_after += -(y[i] * mua.ln() + (1.0 - y[i]) * (1.0 - mua).ln());
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online Beta GLM",
            "logit quasi-likelihood on (0,1); skipped rows warn and do not abort",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlineBetaRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut eta = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                eta += self.coef[j] * x.get(i, j);
            }
            let eta = eta.clamp(-20.0, 20.0);
            1.0 / (1.0 + (-eta).exp())
        })))
    }
}

/// Online log-cosh regressor (smooth L1).
///
/// SGD on \(\log\cosh(y-\eta)\). Distinct from [`OnlineHuberRegressor`]
/// (piecewise) and [`OnlineQuantileRegressor`] (pinball).
#[derive(Clone, Debug)]
pub struct OnlineLogCoshRegressor {
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineLogCoshRegressor {
    fn default() -> Self {
        Self {
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineLogCoshRegressor {
    /// Log-cosh regressor with step `learning_rate`.
    pub fn new(learning_rate: f64) -> Self {
        Self {
            learning_rate,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineLogCoshRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineLogCoshRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected log-cosh update"),
            );
        };
        self.initialized = true;
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() {
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let r = (y[i] - eta).clamp(-20.0, 20.0);
            loss_before += r.cosh().ln();
            let g = -r.tanh();
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ra = (y[i] - ea).clamp(-20.0, 20.0);
            loss_after += ra.cosh().ln();
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online log-cosh regressor",
            "SGD on log cosh(y − η); the loss is not identification p",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for OnlineLogCoshRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| {
            let mut s = self.intercept;
            for j in 0..x.ncols().min(self.coef.len()) {
                s += self.coef[j] * x.get(i, j);
            }
            s
        })))
    }
}

/// Online Cauchy regressor (river robust loss).
///
/// SGD on \(\log(1+(r/c)^2)\). Scale \(c\) is not identification `p`. Distinct
/// from [`OnlineHuberRegressor`] (piecewise \(L_2/L_1\)) and
/// [`OnlineLogCoshRegressor`] (log-cosh).
#[derive(Clone, Debug)]
pub struct OnlineCauchyRegressor {
    /// Cauchy scale \(c>0\). Not identification `p`.
    pub scale: f64,
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineCauchyRegressor {
    fn default() -> Self {
        Self {
            scale: 1.0,
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineCauchyRegressor {
    /// Cauchy regressor with scale `scale`.
    pub fn new(scale: f64) -> Self {
        Self {
            scale,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineCauchyRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineCauchyRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected Cauchy update"),
            );
        };
        self.initialized = true;
        let c = if self.scale.is_finite() && self.scale > 0.0 {
            self.scale
        } else {
            1.0
        };
        let c2 = c * c;
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() {
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let r = (y[i] - eta).clamp(-1.0e6, 1.0e6);
            loss_before += (1.0 + (r * r) / c2).ln();
            let g = -2.0 * r / (c2 + r * r);
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ra = (y[i] - ea).clamp(-1.0e6, 1.0e6);
            loss_after += (1.0 + (ra * ra) / c2).ln();
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online Cauchy regressor",
            "SGD on log(1+(r/c)^2); the scale is not identification p",
        );
        finish_explain(ctx, expl)
    }
}

